<?php
class Docente{function __construct(private PDO $db){} function obtenerTodos($b=''){ $s=$this->db->prepare("SELECT * FROM docentes WHERE numero_empleado LIKE ? OR nombre LIKE ? OR apellidos LIKE ? OR especialidad LIKE ? ORDER BY id DESC");$x="%$b%";$s->execute([$x,$x,$x,$x]);return $s->fetchAll();} function obtenerPorId($id){$s=$this->db->prepare("SELECT * FROM docentes WHERE id=?");$s->execute([$id]);return $s->fetch()?:null;} function insertar($d){return $this->db->prepare("INSERT INTO docentes(numero_empleado,nombre,apellidos,correo,especialidad) VALUES(?,?,?,?,?)")->execute([$d['numero_empleado'],$d['nombre'],$d['apellidos'],$d['correo'],$d['especialidad']]);} function actualizar($d){return $this->db->prepare("UPDATE docentes SET numero_empleado=?,nombre=?,apellidos=?,correo=?,especialidad=? WHERE id=?")->execute([$d['numero_empleado'],$d['nombre'],$d['apellidos'],$d['correo'],$d['especialidad'],$d['id']]);} function eliminar($id){return $this->db->prepare("DELETE FROM docentes WHERE id=?")->execute([$id]);}}